let buffer;
let numHarmonics = 5;
let baseAmplitude = 100;
let waveSpeed = 0.01;

// ===== Inicialización =====
function setup() {
  createCanvas(windowWidth, windowHeight);
  buffer = createGraphics(width, height);
  noStroke();
  fill(0, 150, 255, 150); // Azul translúcido para el agua
}

// ===== Dibujo =====
function draw() {
  background(0);
  buffer.background(0, 0);

  // Simulación de ondas usando seno anidado
  for (let x = 0; x < width; x += 5) {
    let y = height / 2;
    let wave = 0;

    // Suma de múltiples ondas con diferentes frecuencias y amplitudes
    for (let i = 0; i < numHarmonics; i++) {
      let freq = pow(2, i) * waveSpeed;
      let amp = baseAmplitude / pow(2, i);
      wave += sin(x * freq + frameCount * 0.01 + i * TWO_PI / numHarmonics)) * amp;
    }

    let waveY = y + wave;
    buffer.ellipse(x, waveY, 10, 10);
  }

  // Dibujar el buffer en la pantalla
  image(buffer, 0, 0);
}

// ===== Adaptación a pantalla =====
function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  buffer = createGraphics(width, height);
}"}
